    geo_json_22d8e3025ae74246b41d936d723f4ca6.bindTooltip(
    function(layer){
    let div = L.DomUtil.create(&#x27;div&#x27;);

    let handleObject = feature =&gt; {
        if (feature === null) {
            return &#x27;&#x27;;
        } else if (typeof(feature)==&#x27;object&#x27;) {
            return JSON.stringify(feature);
        } else {
            return feature;
        }
    }
    let fields = [&quot;country&quot;, &quot;n_clusters&quot;, &quot;od_pct&quot;];
    let aliases = [&quot;Country&quot;, &quot;DHS clusters&quot;, &quot;Households with no toilet (open defecation)&quot;];
    let table = &#x27;&lt;table&gt;&#x27; +
        String(
        fields.map(
        (v,i)=&gt;
        `&lt;tr&gt;
            &lt;th&gt;${aliases[i]}&lt;/th&gt;

            &lt;td&gt;${handleObject(layer.feature.properties[v])}&lt;/td&gt;
        &lt;/tr&gt;`).join(&#x27;&#x27;))
    +&#x27;&lt;/table&gt;&#x27;;
    div.innerHTML=table;

    return div
    }
    ,{
  &quot;sticky&quot;: true,
  &quot;className&quot;: &quot;foliumtooltip&quot;,
});


